"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { AppState } from "@/lib/store";
import { projectFounderFloorQueues } from "@/lib/founder-regeneration";
import { buildActionHeaders } from "@/lib/request-helpers";
import { useSession } from "@/components/session-provider";
import { useRouter } from "next/navigation";
import { getApprovedEntranceZoneCatalog } from "@/lib/entrance-zone-catalog";
import { d16UtilityZones } from "@/lib/domain";

type Bootstrap = AppState & { persistenceRevision?: number | null };
type CaseFileAsset = { id: string; evidenceRef: string; caseId: string; floorLabel?: string; fileName: string; mimeType: string; sizeBytes: number; createdAt: string };
type GoogleUploadState = "NOT_SELECTED" | "SELECTED" | "UPLOADING" | "UPLOADED_NOT_RECORDED" | "RECORDED" | "FAILED";
type UtilityMasterRow = { rowNumber: number; utilityName: string; directionCode: string; attributeText: string; outcome: "GOOD" | "BAD" | "OK-OK" };
type D16DraftRow = { id: string; serialNumber: number; utilityId: string; utilityName: string; floorPlanLabel: string; zone: (typeof d16UtilityZones)[number] };
class ActionError extends Error { constructor(message: string, readonly status: number) { super(message); } }
const uploadHeaders = (role: string) => typeof window !== "undefined" && window.location.hostname === "localhost" ? { "x-uchit-demo-role": role } : undefined;
const readableFileSize = (size: number) => size < 1024 * 1024 ? `${Math.ceil(size / 1024)} KB` : `${(size / (1024 * 1024)).toFixed(1)} MB`;

export function SpatialWorkspace({ focus = "all", caseId: requestedCaseId, floorId: requestedFloorId, fastFlow = false }: { focus?: "all" | "plan" | "orientation" | "gridding"; clientId?: string; caseId?: string; floorId?: string; fastFlow?: boolean }) {
  const { activeUser } = useSession();
  const router = useRouter();
  const [state, setState] = useState<Bootstrap | null>(null);
  const [assets, setAssets] = useState<CaseFileAsset[]>([]);
  const [caseAssets, setCaseAssets] = useState<CaseFileAsset[]>([]);
  const [file, setFile] = useState<File | null>(null);
  const [planUploadState, setPlanUploadState] = useState<GoogleUploadState>("NOT_SELECTED");
  const [planUploadError, setPlanUploadError] = useState("");
  const [caseFile, setCaseFile] = useState<File | null>(null);
  const [planVersion, setPlanVersion] = useState("");
  const [planAssetRef, setPlanAssetRef] = useState("");
  const [markedAssetRef, setMarkedAssetRef] = useState("");
  const [marked16AssetRef, setMarked16AssetRef] = useState("");
  const [marked32File, setMarked32File] = useState<File | null>(null);
  const [marked16File, setMarked16File] = useState<File | null>(null);
  const [marked32UploadState, setMarked32UploadState] = useState<GoogleUploadState>("NOT_SELECTED");
  const [marked16UploadState, setMarked16UploadState] = useState<GoogleUploadState>("NOT_SELECTED");
  const [marked32UploadError, setMarked32UploadError] = useState("");
  const [marked16UploadError, setMarked16UploadError] = useState("");
  const [chooseMarked32FromLibrary, setChooseMarked32FromLibrary] = useState(false);
  const [chooseMarked16FromLibrary, setChooseMarked16FromLibrary] = useState(false);
  const [dualUseConfirmed, setDualUseConfirmed] = useState(false);
  const [has32SectorChakra, setHas32SectorChakra] = useState(false);
  const [has16DirectionMapping, setHas16DirectionMapping] = useState(false);
  const [googleAssetRef, setGoogleAssetRef] = useState("");
  const [googleUploadState, setGoogleUploadState] = useState<GoogleUploadState>("NOT_SELECTED");
  const [googleUploadError, setGoogleUploadError] = useState("");
  // Legacy percentage-marker controls remain mounted only in a hidden,
  // read-only compatibility block until their historical view is extracted.
  const [planPreviewUrl] = useState("");
  const [orientationErrors, setOrientationErrors] = useState<Record<string, string>>({});
  const [openingErrors, setOpeningErrors] = useState<Record<string, string>>({});
  const [degree, setDegree] = useState("");
  const [orientationReason, setOrientationReason] = useState("");
  const [propertyMainGateZoneCode, setPropertyMainGateZoneCode] = useState("");
  const [floorGateZoneCode, setFloorGateZoneCode] = useState("");
  const [entranceZoneReason, setEntranceZoneReason] = useState("");
  const [entranceZoneErrors, setEntranceZoneErrors] = useState<Record<string, string>>({});
  const [openingKind, setOpeningKind] = useState("MAIN_ENTRANCE");
  const [openingX, setOpeningX] = useState("50");
  const [openingY, setOpeningY] = useState("50");
  const [spaceLabel, setSpaceLabel] = useState("");
  const [polygonText, setPolygonText] = useState("");
  const [regenerationReason, setRegenerationReason] = useState("");
  const [utilityMasterRows, setUtilityMasterRows] = useState<UtilityMasterRow[]>([]);
  const [utilityMasterError, setUtilityMasterError] = useState("");
  const [d16DraftRows, setD16DraftRows] = useState<D16DraftRow[]>([]);
  const [d16UtilityName, setD16UtilityName] = useState("");
  const [d16Zone, setD16Zone] = useState<(typeof d16UtilityZones)[number]>("SE");
  const [d16FloorPlanLabel, setD16FloorPlanLabel] = useState("");
  const [replacementVersionId, setReplacementVersionId] = useState<Record<string, string>>({});
  const [busy, setBusy] = useState(true);
  const [message, setMessage] = useState("Loading project and floor setup...");
  const keys = useRef<Record<string, string>>({});
  const googleFileRef = useRef<HTMLInputElement>(null);
  const googleAssetControlRef = useRef<HTMLSelectElement>(null);
  const degreeRef = useRef<HTMLInputElement>(null);
  const reasonRef = useRef<HTMLTextAreaElement>(null);
  const propertyGateRef = useRef<HTMLSelectElement>(null);
  const floorGateRef = useRef<HTMLSelectElement>(null);

  const refresh = useCallback(async () => {
    setBusy(true);
    try {
      const response = await fetch("/api/bootstrap", { cache: "no-store" });
      if (!response.ok) throw new Error("Project setup could not be loaded.");
      const next = await response.json() as Bootstrap;
      setState(next);
      setMessage("Project and floor setup is up to date.");
    } catch (error) { setMessage(error instanceof Error ? error.message : "Project setup could not be loaded."); }
    finally { setBusy(false); }
  }, []);

  useEffect(() => { void refresh(); }, [refresh]);
  // Founder spatial work is bound to the exact permission-validated route
  // context. Case/floor switching belongs to the global selector; this
  // workspace never chooses the first client, case, or floor.
  const requestedCaseMissing = Boolean(requestedCaseId && state && !state.vastuCases.some((item) => item.id === requestedCaseId));
  const caseRecord = requestedCaseId ? state?.vastuCases.find((item) => item.id === requestedCaseId) : undefined;
  const client = caseRecord ? state?.clients.find((item) => item.id === caseRecord.clientId) : undefined;
  const project = state?.projects.find((item) => item.id === caseRecord?.projectId);
  const floors = state?.floorWorkspaces.filter((item) => item.caseId === caseRecord?.id && item.projectId === project?.id) ?? [];
  const requestedFloorMissing = Boolean(requestedFloorId && state && !state.floorWorkspaces.some((item) => item.id === requestedFloorId));
  const requestedFloorMismatch = Boolean(requestedFloorId && caseRecord && state && state.floorWorkspaces.some((item) => item.id === requestedFloorId && item.caseId !== caseRecord.id));
  const floor = requestedFloorId ? floors.find((item) => item.id === requestedFloorId) : undefined;
  const plan = state?.planVersions.find((item) => item.caseId === caseRecord?.id && item.floorId === floor?.id && item.status === "CURRENT");
  const replacingPlan = Boolean(plan && planAssetRef && planAssetRef !== plan.protectedFileRef);
  const selectedPlanIsCurrent = Boolean(plan && planAssetRef === plan.protectedFileRef);
  const markedEvidence = state?.spatialEvidenceVersions.find((item) => item.caseId === caseRecord?.id && item.floorId === floor?.id && item.planVersionId === plan?.id && item.kind === "HAND_MARKED_PLAN" && item.classification === "MARKED_32D_CHAKRA_V1" && item.has32SectorChakra === true && item.status === "CURRENT");
  const marked16Evidence = state?.spatialEvidenceVersions.find((item) => item.caseId === caseRecord?.id && item.floorId === floor?.id && item.planVersionId === plan?.id && item.kind === "HAND_MARKED_PLAN" && item.classification === "MARKED_16D_MAPPING_V1" && item.has16DirectionMapping === true && item.status === "CURRENT");
  const selectedMarkedIsCurrent = Boolean(markedEvidence && markedAssetRef === markedEvidence.protectedFileRef);
  const selectedMarked16IsCurrent = Boolean(marked16Evidence && marked16AssetRef === marked16Evidence.protectedFileRef);
  const googleEvidence = state?.spatialEvidenceVersions.find((item) => item.caseId === caseRecord?.id && item.kind === "GOOGLE_EARTH_ORIENTATION" && item.status === "CURRENT");
  const replacingGoogleEvidence = Boolean(googleEvidence && googleAssetRef && googleAssetRef !== googleEvidence.protectedFileRef);
  const selectedGoogleEvidenceIsCurrent = Boolean(googleEvidence && googleAssetRef === googleEvidence.protectedFileRef);
  const orientation = state?.orientationVersions.find((item) => item.caseId === caseRecord?.id && item.status === "LOCKED");
  const openings = state?.openingMappings.filter((item) => item.caseId === caseRecord?.id && item.floorId === floor?.id && item.planVersionId === plan?.id && item.orientationVersionId === orientation?.id) ?? [];
  const openingCoordinateError = (value: string) => !value.trim() || !Number.isFinite(Number(value)) || Number(value) < 0 || Number(value) > 100 ? "Enter a percentage from 0 to 100." : "";
  const openingXError = openingCoordinateError(openingX); const openingYError = openingCoordinateError(openingY);
  const openingDuplicate = openings.some((item) => item.kind === openingKind && item.markerX === Number(openingX) / 100 && item.markerY === Number(openingY) / 100);
  const spaces = state?.spaceMappings.filter((item) => item.caseId === caseRecord?.id && item.floorId === floor?.id && item.planVersionId === plan?.id && item.orientationVersionId === orientation?.id) ?? [];
  const readyForMapping = Boolean(plan && markedEvidence && marked16Evidence && orientation);
  const founderQueues = state && caseRecord ? projectFounderFloorQueues(state, caseRecord.id) : [];
  const planAsset = assets.find((item) => item.evidenceRef === plan?.protectedFileRef);
  const marked32Asset = assets.find((item) => item.evidenceRef === (markedEvidence?.protectedFileRef ?? markedAssetRef));
  const marked16Asset = assets.find((item) => item.evidenceRef === (marked16Evidence?.protectedFileRef ?? marked16AssetRef));
  const sameMarkedSource = Boolean((markedEvidence?.protectedFileRef ?? markedAssetRef) && (markedEvidence?.protectedFileRef ?? markedAssetRef) === (marked16Evidence?.protectedFileRef ?? marked16AssetRef));
  const entranceCatalog = state ? getApprovedEntranceZoneCatalog(state, caseRecord?.organisationId) : { ready: false as const, reason: "Loading approved 32-zone catalog.", zones: [] };
  const propertyMainGateZone = state?.entranceZoneVersions?.find((item) => item.caseId === caseRecord?.id && item.scope === "PROPERTY_MAIN_GATE" && item.status === "CURRENT");
  const floorGateZone = state?.entranceZoneVersions?.find((item) => item.caseId === caseRecord?.id && item.floorId === floor?.id && item.scope === "FLOOR_PRIMARY_ENTRANCE" && item.status === "CURRENT");
  const propertyZoneDefinition = entranceCatalog.zones.find((item) => item.code === (propertyMainGateZoneCode || propertyMainGateZone?.zoneCode));
  const floorZoneDefinition = entranceCatalog.zones.find((item) => item.code === (floorGateZoneCode || floorGateZone?.zoneCode));
  const entranceZonesConfirmed = Boolean(propertyMainGateZone || floorGateZone);
  const isV1Spatial = caseRecord?.evaluationArchitectureVersion === "V1" && floor?.evaluationArchitectureVersion === "V1";
  const v1D8 = state?.d8OrientationSnapshots.find((item) => item.caseId === caseRecord?.id && item.status === "FINALIZED");
  const v1D16Draft = state?.d16UtilityMappingVersions.find((item) => item.caseId === caseRecord?.id && item.floorId === floor?.id && item.status === "DRAFT");
  const mainEntrance = openings.find((item) => item.kind === "MAIN_ENTRANCE" && item.verified);
  const griddingComplete = Boolean(plan && orientation?.status === "LOCKED" && markedEvidence?.has32SectorChakra && marked16Evidence?.has16DirectionMapping && entranceZonesConfirmed);
  const marked32History = state?.spatialEvidenceVersions.filter((item) => item.caseId === caseRecord?.id && item.floorId === floor?.id && item.planVersionId === plan?.id && item.classification === "MARKED_32D_CHAKRA_V1") ?? [];
  const marked16History = state?.spatialEvidenceVersions.filter((item) => item.caseId === caseRecord?.id && item.floorId === floor?.id && item.planVersionId === plan?.id && item.classification === "MARKED_16D_MAPPING_V1") ?? [];

  useEffect(() => {
    if (!orientation) return;
    setDegree(String(orientation.exactDegree));
    setOrientationReason(orientation.lockReason ?? "");
    setGoogleAssetRef(googleEvidence?.protectedFileRef ?? "");
    setGoogleUploadState(googleEvidence ? "RECORDED" : "NOT_SELECTED");
    setCaseFile(null);
  }, [orientation?.id, googleEvidence?.id]);
  useEffect(() => {
    if (!plan) return;
    setPlanVersion(plan.versionLabel);
    setPlanAssetRef(plan.protectedFileRef);
    setPlanUploadState("RECORDED");
    setFile(null);
  }, [plan?.id]);
  useEffect(() => {
    if (markedEvidence) { setMarkedAssetRef(markedEvidence.protectedFileRef); setHas32SectorChakra(true); setMarked32UploadState("RECORDED"); }
    if (marked16Evidence) { setMarked16AssetRef(marked16Evidence.protectedFileRef); setHas16DirectionMapping(true); setMarked16UploadState("RECORDED"); }
    setDualUseConfirmed(Boolean(markedEvidence?.dualPurposeMarkedLayersConfirmed || marked16Evidence?.dualPurposeMarkedLayersConfirmed));
  }, [markedEvidence?.id, marked16Evidence?.id]);
  useEffect(() => {
    setPropertyMainGateZoneCode(propertyMainGateZone?.zoneCode ?? "");
    setFloorGateZoneCode(floorGateZone?.zoneCode ?? "");
    setEntranceZoneReason("");
    setEntranceZoneErrors({});
  }, [propertyMainGateZone?.id, floorGateZone?.id, caseRecord?.id, floor?.id]);
  useEffect(() => {
    if (!isV1Spatial || focus !== "gridding") return;
    let active = true;
    void fetch("/api/utility/master", { cache: "no-store" }).then(async (response) => {
      const result = await response.json() as { utilityMaster?: { rows?: UtilityMasterRow[] }; error?: string };
      if (!response.ok || !result.utilityMaster?.rows) throw new Error(result.error ?? "The approved Utility Master could not be loaded.");
      if (active) { setUtilityMasterRows(result.utilityMaster.rows); setUtilityMasterError(""); }
    }).catch((error) => { if (active) setUtilityMasterError(error instanceof Error ? error.message : "The approved Utility Master could not be loaded."); });
    return () => { active = false; };
  }, [isV1Spatial, focus]);

  const loadAssets = useCallback(async (activeCaseId: string, floorLabel?: string) => {
    const query = new URLSearchParams({ caseId: activeCaseId }); if (floorLabel) query.set("floorLabel", floorLabel);
    const response = await fetch(`/api/case-files?${query}`, { cache: "no-store", headers: uploadHeaders(activeUser.role) });
    const result = await response.json();
    if (!response.ok || result.ok === false) throw new ActionError(typeof result.error === "string" ? result.error : "Protected files could not be loaded.", response.status);
    return result.assets as CaseFileAsset[];
  }, [activeUser.role]);

  useEffect(() => {
    setAssets([]); setCaseAssets([]);
    if (!caseRecord || !floor) return;
    void Promise.all([loadAssets(caseRecord.id, floor.floorLabel), loadAssets(caseRecord.id)]).then(([floorFiles, projectFiles]) => { setAssets(floorFiles); setCaseAssets(projectFiles); })
      .catch((error) => setMessage(error instanceof Error ? error.message : "Protected files could not be loaded."));
  }, [caseRecord?.id, floor?.id, floor?.floorLabel, loadAssets]);

  function key(action: string) { keys.current[action] ??= crypto.randomUUID(); return keys.current[action]; }
  async function run(action: string, fields: Record<string, unknown>, success: string, recordVersion = caseRecord?.recordVersion ?? 0) {
    if (!state || !caseRecord) return false;
    setBusy(true);
    try {
      const response = await fetch("/api/actions", { method: "POST", headers: buildActionHeaders(activeUser.role), body: JSON.stringify({ action, caseId: caseRecord.id,
        ...fields, idempotencyKey: key(action), expectedRecordVersion: recordVersion, expectedRevision: state.persistenceRevision ?? null }) });
      const result = await response.json();
      if (!response.ok || result.ok === false) throw new ActionError(typeof result.error === "string" ? result.error : "The step could not be saved.", response.status);
      delete keys.current[action]; await refresh(); router.refresh(); setMessage(success); return true;
    } catch (error) {
      if (error instanceof ActionError && error.status === 409) setMessage(`${error.message} Reload and review the current version. Nothing was silently retried.`);
      else if (error instanceof ActionError && error.status === 428) setMessage("Reload the latest case before saving this protected step.");
      else setMessage(error instanceof Error ? error.message : "The step could not be saved.");
    } finally { setBusy(false); }
    return false;
  }

  async function upload(selected: File | null, floorLabel?: string, onUploaded?: (asset: CaseFileAsset) => void, onFailed?: (error: string) => void) {
    if (!selected || !caseRecord) return;
    if (!["application/pdf", "image/png", "image/jpeg", "image/webp"].includes(selected.type) || selected.size < 1 || selected.size > 20 * 1024 * 1024) {
      const explanation = "Choose a PDF, PNG, JPG, or WebP file from 1 byte up to 20 MB.";
      setMessage(explanation); onFailed?.(explanation); return;
    }
    setBusy(true);
    try {
      const body = new FormData(); body.set("file", selected); body.set("caseId", caseRecord.id); if (floorLabel) body.set("floorLabel", floorLabel);
      const response = await fetch("/api/case-files", { method: "POST", headers: uploadHeaders(activeUser.role), body });
      const result = await response.json(); if (!response.ok || result.ok === false) throw new Error(typeof result.error === "string" ? result.error : "Upload failed.");
      const refreshed = await loadAssets(caseRecord.id, floorLabel); if (floorLabel) setAssets(refreshed); else setCaseAssets(refreshed);
      const uploaded = result.asset as CaseFileAsset;
      if (uploaded) onUploaded?.(uploaded);
      // The completed upload is now represented by its protected asset record.
      // Clear the browser File object so the same bytes cannot be uploaded again
      // accidentally; choosing another file is an explicit replacement action.
      if (floorLabel) setFile(null); else setCaseFile(null);
      setMessage("Protected file uploaded. Choose it below to record the version.");
    } catch (error) { const explanation = error instanceof Error ? error.message : "Upload failed."; setMessage(explanation); onFailed?.(explanation); }
    finally { setBusy(false); }
  }

  function degreeValidation(value: string) {
    if (value.trim() === "") return "Enter the exact orientation degree.";
    const numericDegree = Number(value);
    return !Number.isFinite(numericDegree) || numericDegree < 0 || numericDegree >= 360 ? "Enter a degree from 0 inclusive to less than 360." : "";
  }

  function reasonValidation(value: string) {
    return value.trim().length < 20 ? "Explain why this orientation is correct using at least 20 characters." : "";
  }

  const currentDegreeError = degreeValidation(degree);
  const currentReasonError = reasonValidation(orientationReason);
  const orientationUnchanged = Boolean(orientation && googleEvidence?.id === orientation.googleEarthEvidenceVersionId && Number(degree) === orientation.exactDegree && orientationReason.trim() === (orientation.lockReason ?? "").trim());
  const nativeD8Ready = Boolean(isV1Spatial && orientation && v1D8?.sourceOrientationVersionId === orientation.id);

  function validateOrientation() {
    const errors: Record<string, string> = {};
    if (!googleAssetRef && !googleEvidence) errors.googleEvidence = "Upload and select the Google Earth screenshot before recording orientation evidence.";
    const degreeError = degreeValidation(degree); if (degreeError) errors.degree = degreeError;
    const reasonError = reasonValidation(orientationReason); if (reasonError) errors.reason = reasonError;
    setOrientationErrors(errors);
    return errors;
  }

  function focusFirstOrientationError(errors: Record<string, string>) {
    if (errors.googleEvidence) (googleAssetRef ? googleAssetControlRef : googleFileRef).current?.focus();
    else if (errors.degree) degreeRef.current?.focus();
    else if (errors.reason) reasonRef.current?.focus();
  }

  useEffect(() => {
    const hasUnsavedOrientation = ["SELECTED", "UPLOADING", "UPLOADED_NOT_RECORDED"].includes(googleUploadState)
      || degree.trim() !== (orientation ? String(orientation.exactDegree) : "")
      || orientationReason.trim() !== (orientation?.lockReason ?? "");
    const hasUnsavedPlan = ["SELECTED", "UPLOADING", "UPLOADED_NOT_RECORDED"].includes(planUploadState)
      || planVersion.trim() !== (plan?.versionLabel ?? "")
      || planAssetRef !== (plan?.protectedFileRef ?? "");
    const hasUnsavedGridding = ["SELECTED", "UPLOADING", "UPLOADED_NOT_RECORDED"].includes(marked32UploadState)
      || ["SELECTED", "UPLOADING", "UPLOADED_NOT_RECORDED"].includes(marked16UploadState)
      || propertyMainGateZoneCode !== (propertyMainGateZone?.zoneCode ?? "")
      || floorGateZoneCode !== (floorGateZone?.zoneCode ?? "")
      || Boolean(entranceZoneReason.trim());
    if (!hasUnsavedOrientation && !hasUnsavedPlan && !hasUnsavedGridding) return;
    const warn = (event: BeforeUnloadEvent) => { event.preventDefault(); event.returnValue = ""; };
    window.addEventListener("beforeunload", warn);
    return () => window.removeEventListener("beforeunload", warn);
  }, [googleUploadState, degree, orientationReason, planUploadState, planVersion, planAssetRef, marked32UploadState, marked16UploadState, propertyMainGateZoneCode, floorGateZoneCode, entranceZoneReason, propertyMainGateZone?.id, floorGateZone?.id, orientation?.id, orientation?.exactDegree, orientation?.lockReason, plan?.id, plan?.versionLabel, plan?.protectedFileRef]);

  const polygon = useMemo(() => polygonText.split(";").map((pair) => pair.trim()).filter(Boolean).map((pair) => {
    const [x, y] = pair.split(",").map(Number); return { x: x / 100, y: y / 100 };
  }), [polygonText]);

  function replacementOptions(targetType: string) {
    if (!state || !caseRecord || !floor || !plan || !orientation) return [] as Array<{ id: string; label: string }>;
    if (targetType === "OPENING_MAPPING") return state.openingMappings.filter((item) => item.caseId === caseRecord.id && item.floorId === floor.id && item.planVersionId === plan.id && item.orientationVersionId === orientation.id).map((item) => ({ id: item.id, label: `${item.kind.replaceAll("_", " ")} · ${item.createdAt}` }));
    if (targetType === "SPACE_MAPPING") return state.spaceMappings.filter((item) => item.caseId === caseRecord.id && item.floorId === floor.id && item.planVersionId === plan.id && item.orientationVersionId === orientation.id).map((item) => ({ id: item.id, label: `${item.spaceLabel} · ${item.createdAt}` }));
    if (targetType === "UTILITY_EVALUATION") return state.evaluationSnapshots.filter((item) => item.caseId === caseRecord.id && item.floorId === floor.id && item.planVersionId === plan.id && item.orientationVersionId === orientation.id).map((item) => ({ id: item.id, label: item.snapshotName }));
    if (targetType === "SHAKTI_EVALUATION") return state.shaktiSnapshots.filter((item) => item.caseId === caseRecord.id && item.floorId === floor.id && item.planVersionId === plan.id && item.orientationVersionId === orientation.id).map((item) => ({ id: item.id, label: `Shakti evaluation · ${item.id.slice(-8)}` }));
    if (targetType === "FINDING") return state.assessmentObservations.filter((item) => item.caseId === caseRecord.id && item.floorId === floor.id).map((item) => ({ id: item.id, label: item.title }));
    return state.reportVersions.filter((item) => item.caseId === caseRecord.id && item.floorId === floor.id && item.artifact?.templateVersion === "uchit-verdict/v3").map((item) => ({ id: item.id, label: item.versionLabel }));
  }

  const entranceZoneChanged = Boolean(
    (propertyMainGateZone && propertyMainGateZone.zoneCode !== propertyMainGateZoneCode)
    || (floorGateZone && floorGateZone.zoneCode !== floorGateZoneCode)
  );
  function validateEntranceZones() {
    const errors: Record<string, string> = {};
    if (!propertyMainGateZoneCode && !floorGateZoneCode) {
      errors.propertyMainGate = "Choose a property main gate or floor entrance zone.";
      errors.floorGate = "Choose a property main gate or floor entrance zone.";
    }
    if (!entranceCatalog.ready) errors.catalog = entranceCatalog.reason;
    if (entranceZoneChanged && entranceZoneReason.trim().length < 20) errors.reason = "Explain the successor classification using at least 20 characters.";
    setEntranceZoneErrors(errors);
    if (errors.propertyMainGate) propertyGateRef.current?.focus();
    else if (errors.floorGate) floorGateRef.current?.focus();
    return errors;
  }
  function selectMainEntranceFromPreview(event: React.MouseEvent<HTMLButtonElement>) {
    const rect = event.currentTarget.getBoundingClientRect();
    setOpeningKind("MAIN_ENTRANCE"); setOpeningX((((event.clientX - rect.left) / rect.width) * 100).toFixed(2)); setOpeningY((((event.clientY - rect.top) / rect.height) * 100).toFixed(2)); setOpeningErrors({});
  }

  const evidenceHistoryDetails = <details className="card span-12"><summary>Details · evidence version history</summary><div className="two-col"><section><h3>32-sector versions</h3>{marked32History.length ? <ul>{marked32History.map((item) => <li key={item.id}><strong>{assets.find((asset) => asset.evidenceRef === item.protectedFileRef)?.fileName ?? "Protected file"}</strong> · {item.status} · {item.createdAt}</li>)}</ul> : <p className="meta">No recorded 32-sector evidence version.</p>}</section><section><h3>16-direction versions</h3>{marked16History.length ? <ul>{marked16History.map((item) => <li key={item.id}><strong>{assets.find((asset) => asset.evidenceRef === item.protectedFileRef)?.fileName ?? "Protected file"}</strong> · {item.status} · {item.createdAt}</li>)}</ul> : <p className="meta">No recorded 16-direction evidence version.</p>}</section></div><p className="meta">Replacement creates an immutable successor; prior versions are retained and never deleted.</p></details>;

  const v1CasePropertyContext = state?.casePropertyContexts.find((item) => item.caseId === caseRecord?.id && item.projectId === project?.id);
  const v1D16 = state?.d16UtilityMappingVersions.find((item) => item.caseId === caseRecord?.id && item.floorId === floor?.id && item.status === "FINALIZED");
  const d16NeedsProvenanceRepair = Boolean(v1D16 && (!v1D16.methodologyVersionId || !v1D16.methodologyContentHash || !v1D16.utilityMasterSourceVersion || !v1D16.utilityMasterWorkbookHash || !v1D16.utilityMasterAdapterVersion));
  const d16UtilityOptions = [...new Set(utilityMasterRows.map((item) => item.utilityName))].sort();
  const d16ZoneOptions = d16UtilityName ? [...new Set(utilityMasterRows.filter((item) => item.utilityName === d16UtilityName && (d16UtilityZones as readonly string[]).includes(item.directionCode)).map((item) => item.directionCode as (typeof d16UtilityZones)[number]))] : [];
  const selectedD16MasterRow = utilityMasterRows.find((item) => item.utilityName === d16UtilityName && item.directionCode === d16Zone);
  const addD16Row = () => {
    if (!selectedD16MasterRow) return;
    setD16DraftRows((current) => [...current, { id: crypto.randomUUID(), serialNumber: current.length + 1, utilityId: `utilitymaster-row-${selectedD16MasterRow.rowNumber}`, utilityName: selectedD16MasterRow.utilityName, floorPlanLabel: d16FloorPlanLabel.trim() || selectedD16MasterRow.utilityName, zone: d16Zone }]);
  };
  useEffect(() => {
    if (!v1D16Draft) { setD16DraftRows([]); return; }
    setD16DraftRows(v1D16Draft.rows as D16DraftRow[]);
  }, [v1D16Draft?.id, v1D16Draft?.recordVersion]);
  if (isV1Spatial && focus === "gridding" && !fastFlow) return <section className="section-grid spatial-workspace spatial-step-six" aria-labelledby="spatial-title">
    <div className="card span-12"><div className="eyebrow">Founder Step 06 · V1</div><h1 id="spatial-title">Review V1 spatial authority</h1><p className="subtle">V1 progression uses the certified Case Property Context, D8 orientation and finalized D16 floor mapping. Legacy Manual Utility Sheet, Shakti and marked-plan controls are not V1 gates.</p><div className="founder-context-bar" aria-label="Locked spatial context"><span>Case</span><strong>{caseRecord?.caseNumber ?? "Select a case"}</strong><span aria-hidden="true">→</span><span>{project?.propertyName ?? "Project unavailable"}</span><span aria-hidden="true">→</span><span>{floor?.floorLabel ?? "Select a floor"}</span></div><div className="two-col"><div className="focused-summary"><strong>Case Property Context</strong><span>{v1CasePropertyContext ? "Recorded" : "Required"}</span></div><div className="focused-summary"><strong>D8 orientation</strong><span>{v1D8 ? `${v1D8.direction} · ${v1D8.exactDegree}° · FINALIZED` : "Required"}</span></div><div className="focused-summary"><strong>D16 floor mapping</strong><span>{v1D16 ? `${v1D16.rows.length} row(s) · FINALIZED` : v1D16Draft ? `${v1D16Draft.rows.length} row(s) · DRAFT` : "Required"}</span></div></div></div>

    {v1D16 && d16NeedsProvenanceRepair ? <div className="card span-12"><div className="eyebrow">D16 provenance recovery</div><h2>Certified successor required</h2><p className="subtle">The immutable finalized D16 version predates the required methodology provenance. Create a native successor from the unchanged rows; the successor will record this as post-hoc source certification.</p><button className="button" type="button" disabled={Boolean(v1D16Draft)} onClick={() => void run("d16-mapping-successor-v1", { predecessorId: v1D16.id, rows: v1D16.rows }, "Provenance-complete D16 successor draft created.")}>Create provenance-complete D16 successor</button>{v1D16Draft ? <button className="button" type="button" disabled={!v1D16Draft.rows.length} onClick={() => void run("d16-mapping-finalize-v1", { mappingId: v1D16Draft.id }, "Provenance-complete D16 mapping finalized.", v1D16Draft.recordVersion)}>Finalize provenance-complete D16</button> : null}</div> : null}
    {!v1D16 ? <div className="card span-12"><div className="eyebrow">Native D16 Floor Utility Mapping</div><h2>{v1D16Draft ? "Review current D16 draft" : "Create D16 draft"}</h2><p className="subtle">Choose a canonical Utility Master utility and an explicit 16-direction floor zone. Each row remains independent, including same-zone utilities.</p>{utilityMasterError ? <p className="field-error" role="alert">{utilityMasterError}</p> : null}<div className="two-col"><div className="field"><label htmlFor="d16-utility">Canonical Utility Master utility</label><select id="d16-utility" value={d16UtilityName} onChange={(event) => { setD16UtilityName(event.target.value); setD16Zone("SE"); }} disabled={Boolean(v1D16Draft)}><option value="">Choose a canonical utility</option>{d16UtilityOptions.map((name) => <option key={name} value={name}>{name}</option>)}</select></div><div className="field"><label htmlFor="d16-zone">Explicit D16 zone</label><select id="d16-zone" value={d16Zone} onChange={(event) => setD16Zone(event.target.value as (typeof d16UtilityZones)[number])} disabled={Boolean(v1D16Draft) || !d16UtilityName}><option value="">Choose a zone</option>{d16ZoneOptions.map((zone) => <option key={zone} value={zone}>{zone}</option>)}</select></div></div><div className="field"><label htmlFor="d16-floor-plan-label">Floor plan label</label><input id="d16-floor-plan-label" value={d16FloorPlanLabel} onChange={(event) => setD16FloorPlanLabel(event.target.value)} placeholder="Example: Study" disabled={Boolean(v1D16Draft)} /></div><p className="meta">{selectedD16MasterRow ? `Utility Master result: ${selectedD16MasterRow.outcome} · ${selectedD16MasterRow.attributeText}` : "Select a canonical utility and a zone with an approved Utility Master row."}</p><button className="button-secondary" type="button" disabled={Boolean(v1D16Draft) || !selectedD16MasterRow || !plan || !v1D8} onClick={addD16Row}>Add utility row</button><ul>{d16DraftRows.map((row) => { const source = utilityMasterRows.find((item) => item.utilityName === row.utilityName && item.directionCode === row.zone); return <li key={row.id}>{row.utilityName} · {row.zone} · {source?.outcome ?? "REVIEW_REQUIRED"} · {row.floorPlanLabel}{!v1D16Draft ? <button className="button-secondary" type="button" onClick={() => setD16DraftRows((current) => current.filter((item) => item.id !== row.id).map((item, index) => ({ ...item, serialNumber: index + 1 })))}>Remove</button> : null}</li>; })}</ul><button className="button" type="button" disabled={Boolean(v1D16Draft) || !d16DraftRows.length || !plan || !v1D8 || !v1CasePropertyContext || Boolean(utilityMasterError)} onClick={() => void run("d16-mapping-draft-v1", { projectId: project?.id, floorId: floor?.id, rows: d16DraftRows }, "Native V1 D16 draft saved for this floor.")}>Save D16 draft</button>{v1D16Draft ? <button className="button" type="button" disabled={!v1D16Draft.rows.length} onClick={() => void run("d16-mapping-finalize-v1", { mappingId: v1D16Draft.id }, "Native V1 D16 mapping finalized for this floor.", v1D16Draft.recordVersion)}>Finalize D16</button> : null}</div> : null}
  </section>;

  if (focus === "gridding") return <section className="section-grid spatial-workspace spatial-step-six" aria-labelledby="spatial-title">
    <div className="card span-12"><div className="eyebrow">Founder Step 06</div><h1 id="spatial-title">Confirm gridding evidence</h1><p className="subtle">The 32-sector and 16-direction files are manually prepared Founder evidence. Uchit stores and verifies the exact protected versions; it does not infer geometry, sectors, or direction labels.</p><div className="founder-context-bar" aria-label="Locked spatial context"><span>Case</span><strong>{caseRecord?.caseNumber ?? "Select a case"}</strong><span aria-hidden="true">→</span><span>{project?.propertyName ?? "Project unavailable"}</span><span aria-hidden="true">→</span><span>{floor?.floorLabel ?? "Select a floor"}</span></div><div className="pill-row"><span className="pill">Plan {plan ? plan.versionLabel : "required"}</span><span className="pill">Orientation {orientation?.status === "LOCKED" ? `${orientation.exactDegree}° locked` : "required"}</span><span className={`pill ${griddingComplete ? "status-approved" : "status-attention"}`}>{griddingComplete ? "All three tasks complete" : "Required evidence pending"}</span></div>{!caseRecord || !floor ? <p className="blocked-note" role="alert">Select an authorised case and floor before confirming evidence.</p> : null}</div>

    <article className="card span-6" aria-labelledby="task-32d-title"><div className="eyebrow">Task 1 of 3</div><h2 id="task-32d-title">Confirm 32-sector marked evidence</h2><p className="subtle">Choose the manually prepared full-colour evidence for this exact floor and current plan.</p><dl className="focused-summary"><div><dt>Protected file</dt><dd>{marked32Asset?.fileName ?? "Not selected"}</dd></div><div><dt>Evidence version</dt><dd>{markedEvidence ? markedEvidence.id : "Not recorded"}</dd></div><div><dt>Upload status</dt><dd>{marked32Asset ? "Protected file available" : "File required"}</dd></div><div><dt>Confirmation</dt><dd>{markedEvidence?.has32SectorChakra ? "Founder-confirmed" : "Confirmation required"}</dd></div><div><dt>Binding</dt><dd>{floor && plan ? `${floor.floorLabel} · ${plan.versionLabel}` : "Floor and plan required"}</dd></div></dl>{sameMarkedSource ? <p className="meta">The same protected source file is also used for Task 2. Each evidence purpose remains a separate versioned Founder confirmation.</p> : null}<div className={`founder-flow-status ${marked32UploadState === "FAILED" ? "status-blocked" : ["UPLOADED_NOT_RECORDED", "RECORDED"].includes(marked32UploadState) ? "status-ready" : ""}`} role={marked32UploadState === "FAILED" ? "alert" : "status"} aria-live="polite"><strong>Upload status: {marked32UploadState.replaceAll("_", " ")}</strong>{marked32File ? <span className="meta">{marked32File.name.replace(/[\r\n]/g, " ")} · {marked32File.type || "unknown type"} · {readableFileSize(marked32File.size)}</span> : null}{marked32UploadError ? <p>{marked32UploadError}</p> : null}</div><div className="field"><label htmlFor="marked-32-file">Select new 32-sector evidence</label><input id="marked-32-file" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp" onChange={(event) => { const selected = event.target.files?.[0] ?? null; setMarked32File(selected); setMarked32UploadError(""); setMarked32UploadState(selected ? "SELECTED" : "NOT_SELECTED"); }} /><button className="button-secondary" type="button" disabled={!marked32File || busy || !floor} onClick={() => { if (!marked32File) return; setMarked32UploadState("UPLOADING"); void upload(marked32File, floor?.floorLabel, (asset) => { setMarkedAssetRef(asset.evidenceRef); setMarked32File(null); setMarked32UploadState("UPLOADED_NOT_RECORDED"); }, (error) => { setMarked32UploadState("FAILED"); setMarked32UploadError(error); }); }}>{marked32UploadState === "FAILED" ? "Retry secure upload" : "Upload securely"}</button><p className="meta">Accepted: PDF, PNG, JPG or WebP · 1 byte to 20 MB. Upload is protected and floor-scoped.</p></div><details><summary>Choose from protected file library</summary><div className="field"><label htmlFor="marked-asset">Existing protected 32-sector evidence</label><select id="marked-asset" value={markedAssetRef} onChange={(event) => { setMarkedAssetRef(event.target.value); setChooseMarked32FromLibrary(Boolean(event.target.value)); setMarked32UploadState(event.target.value ? "UPLOADED_NOT_RECORDED" : "NOT_SELECTED"); }}><option value="">Choose a protected file</option>{assets.map((asset) => <option key={asset.id} value={asset.evidenceRef}>{asset.fileName}</option>)}</select>{chooseMarked32FromLibrary ? <p className="meta">Selected from the protected floor library.</p> : null}</div></details><label className="check-row" htmlFor="has-32-sector-chakra"><input id="has-32-sector-chakra" type="checkbox" checked={has32SectorChakra} onChange={(event) => setHas32SectorChakra(event.target.checked)} /> I confirm the 32-sector chakra overlay is visibly present.</label>{sameMarkedSource && !selectedMarkedIsCurrent ? <label className="check-row" htmlFor="dual-marked-layers"><input id="dual-marked-layers" type="checkbox" checked={dualUseConfirmed} onChange={(event) => setDualUseConfirmed(event.target.checked)} /> I confirm this one file visibly contains both distinct 32-sector and 16-direction marked layers.</label> : null}<button className="button" type="button" disabled={busy || !floor || !plan || !markedAssetRef || !has32SectorChakra || (sameMarkedSource && !dualUseConfirmed) || selectedMarkedIsCurrent} onClick={() => void run("spatial-evidence-create", { floorId: floor?.id, planVersionId: plan?.id, kind: "HAND_MARKED_PLAN", classification: "MARKED_32D_CHAKRA_V1", has32SectorChakra: true, dualPurposeMarkedLayersConfirmed: sameMarkedSource ? dualUseConfirmed : undefined, evidenceRef: markedAssetRef, fullColourConfirmed: true }, "32-sector chakra evidence recorded and Founder-confirmed.")}>{selectedMarkedIsCurrent ? "32-sector evidence confirmed" : markedEvidence ? "Confirm replacement 32-sector evidence" : "Confirm 32-sector evidence"}</button><p className="meta">{selectedMarkedIsCurrent ? "The current immutable evidence is already confirmed." : !markedAssetRef ? "Upload a new protected file or choose one from the library." : !has32SectorChakra ? "Confirm the visible overlay before saving." : sameMarkedSource && !dualUseConfirmed ? "Confirm the document visibly contains both distinct marked layers." : "Ready to bind this evidence to the selected floor and plan."}</p></article>

    <article className="card span-6" aria-labelledby="task-16d-title"><div className="eyebrow">Task 2 of 3</div><h2 id="task-16d-title">Confirm 16-direction marked evidence</h2><p className="subtle">Choose the manually prepared full-colour mapping for this exact floor and current plan.</p><dl className="focused-summary"><div><dt>Protected file</dt><dd>{marked16Asset?.fileName ?? "Not selected"}</dd></div><div><dt>Evidence version</dt><dd>{marked16Evidence ? marked16Evidence.id : "Not recorded"}</dd></div><div><dt>Upload status</dt><dd>{marked16Asset ? "Protected file available" : "File required"}</dd></div><div><dt>Confirmation</dt><dd>{marked16Evidence?.has16DirectionMapping ? "Founder-confirmed" : "Confirmation required"}</dd></div><div><dt>Binding</dt><dd>{floor && plan ? `${floor.floorLabel} · ${plan.versionLabel}` : "Floor and plan required"}</dd></div></dl>{sameMarkedSource ? <p className="meta">The same protected source file is also used for Task 1. The 16-direction confirmation remains independently recorded.</p> : null}<div className={`founder-flow-status ${marked16UploadState === "FAILED" ? "status-blocked" : ["UPLOADED_NOT_RECORDED", "RECORDED"].includes(marked16UploadState) ? "status-ready" : ""}`} role={marked16UploadState === "FAILED" ? "alert" : "status"} aria-live="polite"><strong>Upload status: {marked16UploadState.replaceAll("_", " ")}</strong>{marked16File ? <span className="meta">{marked16File.name.replace(/[\r\n]/g, " ")} · {marked16File.type || "unknown type"} · {readableFileSize(marked16File.size)}</span> : null}{marked16UploadError ? <p>{marked16UploadError}</p> : null}</div><div className="field"><label htmlFor="marked-16-file">Select new 16-direction evidence</label><input id="marked-16-file" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp" onChange={(event) => { const selected = event.target.files?.[0] ?? null; setMarked16File(selected); setMarked16UploadError(""); setMarked16UploadState(selected ? "SELECTED" : "NOT_SELECTED"); }} /><button className="button-secondary" type="button" disabled={!marked16File || busy || !floor} onClick={() => { if (!marked16File) return; setMarked16UploadState("UPLOADING"); void upload(marked16File, floor?.floorLabel, (asset) => { setMarked16AssetRef(asset.evidenceRef); setMarked16File(null); setMarked16UploadState("UPLOADED_NOT_RECORDED"); }, (error) => { setMarked16UploadState("FAILED"); setMarked16UploadError(error); }); }}>{marked16UploadState === "FAILED" ? "Retry secure upload" : "Upload securely"}</button><p className="meta">Accepted: PDF, PNG, JPG or WebP · 1 byte to 20 MB. Upload is protected and floor-scoped.</p></div><details><summary>Choose from protected file library</summary><div className="field"><label htmlFor="marked-16-asset">Existing protected 16-direction evidence</label><select id="marked-16-asset" value={marked16AssetRef} onChange={(event) => { setMarked16AssetRef(event.target.value); setChooseMarked16FromLibrary(Boolean(event.target.value)); setMarked16UploadState(event.target.value ? "UPLOADED_NOT_RECORDED" : "NOT_SELECTED"); }}><option value="">Choose a protected file</option>{assets.map((asset) => <option key={asset.id} value={asset.evidenceRef}>{asset.fileName}</option>)}</select>{chooseMarked16FromLibrary ? <p className="meta">Selected from the protected floor library.</p> : null}</div></details><label className="check-row" htmlFor="has-16-direction-mapping"><input id="has-16-direction-mapping" type="checkbox" checked={has16DirectionMapping} onChange={(event) => setHas16DirectionMapping(event.target.checked)} /> I confirm this 16-direction mapping belongs to this floor and plan.</label>{sameMarkedSource && !selectedMarked16IsCurrent ? <label className="check-row" htmlFor="dual-marked-layers-16"><input id="dual-marked-layers-16" type="checkbox" checked={dualUseConfirmed} onChange={(event) => setDualUseConfirmed(event.target.checked)} /> I confirm this one file visibly contains both distinct 32-sector and 16-direction marked layers.</label> : null}<button className="button" type="button" disabled={busy || !floor || !plan || !marked16AssetRef || !has16DirectionMapping || (sameMarkedSource && !dualUseConfirmed) || selectedMarked16IsCurrent} onClick={() => void run("spatial-evidence-create", { floorId: floor?.id, planVersionId: plan?.id, kind: "HAND_MARKED_PLAN", classification: "MARKED_16D_MAPPING_V1", has16DirectionMapping: true, dualPurposeMarkedLayersConfirmed: sameMarkedSource ? dualUseConfirmed : undefined, evidenceRef: marked16AssetRef, fullColourConfirmed: true }, "16-direction marked mapping recorded and Founder-confirmed.")}>{selectedMarked16IsCurrent ? "16-direction evidence confirmed" : marked16Evidence ? "Confirm replacement 16-direction evidence" : "Confirm 16-direction evidence"}</button><p className="meta">{selectedMarked16IsCurrent ? "The current immutable evidence is already confirmed." : !marked16AssetRef ? "Upload a new protected file or choose one from the library." : !has16DirectionMapping ? "Confirm exact floor and plan ownership before saving." : sameMarkedSource && !dualUseConfirmed ? "Confirm the document visibly contains both distinct marked layers." : "Ready to bind this evidence to the selected floor and plan."}</p></article>

    <article className="card span-12" aria-labelledby="task-entrance-title"><div className="eyebrow">Task 3 of 3</div><h2 id="task-entrance-title">Mark the main entrance</h2><p className="subtle">Click the current plan preview to place the marker. The percentage fields provide the same accessible placement control and remain the authoritative saved coordinates.</p><div className="spatial-marker-layout"><div className="stage-b-print-sheet spatial-plan-preview-shell">{planPreviewUrl && planAsset?.mimeType.startsWith("image/") ? <img className="stage-b-layout-media" src={planPreviewUrl} alt={`Current plan: ${plan?.versionLabel}`} /> : planPreviewUrl && planAsset?.mimeType === "application/pdf" ? <iframe className="stage-b-layout-media" src={`${planPreviewUrl}#toolbar=0&navpanes=0&scrollbar=0`} title={`Current plan: ${plan?.versionLabel}`} /> : <div className="stage-b-layout-fallback"><span>CURRENT PROTECTED PLAN</span><strong>{plan?.versionLabel ?? "Plan preview unavailable"}</strong><div className="stage-b-plan-lines"><i /><i /><i /><i /><i /></div><small>{planAsset?.fileName ?? "Record the current plan before marking the entrance."}</small></div>}<button type="button" className="spatial-plan-click-target" aria-label="Place main entrance marker on the current plan" disabled={!readyForMapping} onClick={selectMainEntranceFromPreview} />{mainEntrance ? <span className="spatial-main-entrance-marker" style={{ left: `${mainEntrance.markerX * 100}%`, top: `${mainEntrance.markerY * 100}%` }} aria-hidden="true">ME</span> : !openingXError && !openingYError ? <span className="spatial-main-entrance-marker is-draft" style={{ left: `${Number(openingX)}%`, top: `${Number(openingY)}%` }} aria-hidden="true">ME</span> : null}</div><div><div className="two-col"><div className={`field ${openingErrors.x ? "field-invalid" : ""}`}><label htmlFor="opening-x">From left (%)</label><input id="opening-x" type="number" min="0" max="100" value={openingX} aria-invalid={Boolean(openingErrors.x)} aria-describedby={openingErrors.x ? "opening-x-error" : undefined} onBlur={() => setOpeningErrors((current) => ({ ...current, x: openingXError }))} onChange={(event) => { setOpeningX(event.target.value); setOpeningErrors((current) => ({ ...current, x: "" })); }} />{openingErrors.x ? <p id="opening-x-error" className="field-error" role="alert">{openingErrors.x}</p> : null}</div><div className={`field ${openingErrors.y ? "field-invalid" : ""}`}><label htmlFor="opening-y">From top (%)</label><input id="opening-y" type="number" min="0" max="100" value={openingY} aria-invalid={Boolean(openingErrors.y)} aria-describedby={openingErrors.y ? "opening-y-error" : undefined} onBlur={() => setOpeningErrors((current) => ({ ...current, y: openingYError }))} onChange={(event) => { setOpeningY(event.target.value); setOpeningErrors((current) => ({ ...current, y: "" })); }} />{openingErrors.y ? <p id="opening-y-error" className="field-error" role="alert">{openingErrors.y}</p> : null}</div></div><dl className="focused-summary"><div><dt>Plan</dt><dd>{plan?.versionLabel ?? "Required"}</dd></div><div><dt>Orientation</dt><dd>{orientation?.status === "LOCKED" ? `${orientation.exactDegree}° locked` : "Required"}</dd></div><div><dt>Saved marker</dt><dd>{mainEntrance ? `${(mainEntrance.markerX * 100).toFixed(2)}% left · ${(mainEntrance.markerY * 100).toFixed(2)}% top` : "Not recorded"}</dd></div><div><dt>Verification</dt><dd>{mainEntrance ? "Verified" : "Required"}</dd></div></dl><button className="button" type="button" disabled={busy || !readyForMapping || Boolean(openingXError) || Boolean(openingYError) || Boolean(mainEntrance) || openingDuplicate} onClick={() => void run("opening-mapping-create", { floorId: floor?.id, planVersionId: plan?.id, orientationVersionId: orientation?.id, evidenceVersionId: markedEvidence?.id, kind: "MAIN_ENTRANCE", markerX: Number(openingX) / 100, markerY: Number(openingY) / 100, verified: true }, "Verified main entrance marker saved. Direction classification awaits approved methodology.")}>{mainEntrance ? "Main entrance verified" : "Save main entrance"}</button><p className="meta">{!readyForMapping ? "Saving is disabled until the current plan, locked orientation and confirmed 32-sector evidence are ready." : openingXError ? openingXError : openingYError ? openingYError : mainEntrance ? "The saved marker is visible on the current plan and bound to its exact evidence lineage." : "Ready to save the verified marker."}</p></div></div></article>

    <article className="card span-12 entrance-zone-task" aria-labelledby="entrance-zone-task-title">
      <div className="eyebrow">Task 3 of 3</div>
      <h2 id="entrance-zone-task-title">Classify applicable entrance zones</h2>
      <p className="subtle">Record the applicable Founder-classified zone from the active approved 32-zone methodology. A property gate is shared across the project; a floor entrance belongs only to this floor. Record either or both as applicable.</p>
      {!entranceCatalog.ready ? <div className="blocked-note" role="alert"><strong>BLOCKED — METHOD INPUT REQUIRED</strong><p>{entranceCatalog.reason}</p><p>Activate the exact approved 32-zone catalog before confirming an entrance classification.</p></div> : null}
      <div className="two-col">
        <section className={`panel ${entranceZoneErrors.propertyMainGate ? "field-invalid" : ""}`}>
          <div className="eyebrow">Property-level</div><h3>Property main gate zone</h3><p className="meta">Use this when the property/site has a shared main gate. It is optional for an upper-floor-only or apartment scope.</p>
          <div className="field"><label htmlFor="property-main-gate-zone">Approved 32-zone classification</label><select ref={propertyGateRef} id="property-main-gate-zone" value={propertyMainGateZoneCode} aria-invalid={Boolean(entranceZoneErrors.propertyMainGate)} aria-describedby={entranceZoneErrors.propertyMainGate ? "property-main-gate-zone-error" : "property-main-gate-zone-help"} onChange={(event) => { setPropertyMainGateZoneCode(event.target.value); setEntranceZoneErrors((current) => ({ ...current, propertyMainGate: "", floorGate: "" })); }}><option value="">Not recorded</option>{entranceCatalog.zones.map((zone) => <option key={zone.code} value={zone.code}>{zone.code} — {zone.name}</option>)}</select>{entranceZoneErrors.propertyMainGate ? <p id="property-main-gate-zone-error" className="field-error" role="alert">{entranceZoneErrors.propertyMainGate}</p> : <p id="property-main-gate-zone-help" className="meta">Bound to project {project?.propertyName ?? "not available"} and 32D evidence {markedEvidence?.id ?? "required"}.</p>}</div>
          <dl className="focused-summary"><div><dt>Status</dt><dd>{propertyMainGateZone ? "Confirmed" : "Not recorded"}</dd></div><div><dt>Current zone</dt><dd>{propertyMainGateZone ? `${propertyMainGateZone.zoneCode} — ${propertyMainGateZone.zoneNameSnapshot}` : "Not recorded"}</dd></div><div><dt>Evidence version</dt><dd>{propertyMainGateZone?.marked32DEvidenceVersionId ?? markedEvidence?.id ?? "Required"}</dd></div></dl>
        </section>
        <section className={`panel ${entranceZoneErrors.floorGate ? "field-invalid" : ""}`}>
          <div className="eyebrow">Floor-level</div><h3>Floor gate / primary floor entrance zone</h3><p className="meta">Use this when the selected floor has its own primary entrance. It is optional where only the property main gate is relevant.</p>
          <div className="field"><label htmlFor="floor-gate-zone">Approved 32-zone classification</label><select ref={floorGateRef} id="floor-gate-zone" value={floorGateZoneCode} aria-invalid={Boolean(entranceZoneErrors.floorGate)} aria-describedby={entranceZoneErrors.floorGate ? "floor-gate-zone-error" : "floor-gate-zone-help"} onChange={(event) => { setFloorGateZoneCode(event.target.value); setEntranceZoneErrors((current) => ({ ...current, propertyMainGate: "", floorGate: "" })); }}><option value="">Not recorded</option>{entranceCatalog.zones.map((zone) => <option key={zone.code} value={zone.code}>{zone.code} — {zone.name}</option>)}</select>{entranceZoneErrors.floorGate ? <p id="floor-gate-zone-error" className="field-error" role="alert">{entranceZoneErrors.floorGate}</p> : <p id="floor-gate-zone-help" className="meta">Bound to {floor?.floorLabel ?? "the selected floor"}, plan {plan?.versionLabel ?? "required"}, and 32D evidence {markedEvidence?.id ?? "required"}.</p>}</div>
          <dl className="focused-summary"><div><dt>Status</dt><dd>{floorGateZone ? "Confirmed" : "Not recorded"}</dd></div><div><dt>Current zone</dt><dd>{floorGateZone ? `${floorGateZone.zoneCode} — ${floorGateZone.zoneNameSnapshot}` : "Not recorded"}</dd></div><div><dt>Evidence version</dt><dd>{floorGateZone?.marked32DEvidenceVersionId ?? markedEvidence?.id ?? "Required"}</dd></div></dl>
        </section>
      </div>
      {entranceZoneChanged ? <div className={`field ${entranceZoneErrors.reason ? "field-invalid" : ""}`}><label htmlFor="entrance-zone-reason">Reason for successor classification</label><textarea id="entrance-zone-reason" value={entranceZoneReason} minLength={20} maxLength={500} aria-invalid={Boolean(entranceZoneErrors.reason)} aria-describedby={entranceZoneErrors.reason ? "entrance-zone-reason-error" : "entrance-zone-reason-help"} onChange={(event) => { setEntranceZoneReason(event.target.value); setEntranceZoneErrors((current) => ({ ...current, reason: "" })); }} />{entranceZoneErrors.reason ? <p id="entrance-zone-reason-error" className="field-error" role="alert">{entranceZoneErrors.reason}</p> : <p id="entrance-zone-reason-help" className="meta">A changed confirmed zone creates an immutable successor and invalidates only its affected downstream lineage.</p>}</div> : null}
      <button className="button" type="button" disabled={busy || !plan || !markedEvidence || !entranceCatalog.ready} onClick={() => { const errors = validateEntranceZones(); if (Object.keys(errors).length) return; void run("entrance-zones-confirm", { floorId: floor?.id, planVersionId: plan?.id, marked32EvidenceVersionId: markedEvidence?.id, propertyMainGateZoneCode: propertyMainGateZoneCode || undefined, floorGateZoneCode: floorGateZoneCode || undefined, reason: entranceZoneReason || undefined }, "Entrance zones confirmed against the exact 32D evidence and methodology version."); }}>Confirm entrance zones</button>
      <p className="meta">{!plan ? "Confirmation is disabled until the current plan is recorded." : !markedEvidence ? "Confirmation is disabled until current Founder-confirmed 32-sector evidence is recorded." : !entranceCatalog.ready ? entranceCatalog.reason : entranceZonesConfirmed && !entranceZoneChanged ? `Confirmed: ${[propertyMainGateZone ? `property ${propertyMainGateZone.zoneCode} — ${propertyMainGateZone.zoneNameSnapshot}` : "", floorGateZone ? `${floor?.floorLabel ?? "floor"} ${floorGateZone.zoneCode} — ${floorGateZone.zoneNameSnapshot}` : ""].filter(Boolean).join("; ")}.` : "Choose at least one applicable zone, then confirm."}</p>
      {(propertyZoneDefinition || floorZoneDefinition) ? <details><summary>Internal details · owner interpretation</summary><p className="subtle">The wording below is the immutable owner source text. It is not approved client-facing presentation copy.</p><dl className="focused-summary">{propertyZoneDefinition ? <div><dt>Property main gate · {propertyZoneDefinition.code} · {propertyZoneDefinition.classification}</dt><dd>{propertyZoneDefinition.ownerSourceText}</dd><dd className="meta">Presentation text: REVIEW REQUIRED</dd></div> : null}{floorZoneDefinition ? <div><dt>Floor entrance · {floorZoneDefinition.code} · {floorZoneDefinition.classification}</dt><dd>{floorZoneDefinition.ownerSourceText}</dd><dd className="meta">Presentation text: REVIEW REQUIRED</dd></div> : null}</dl></details> : null}
      {openings.length ? <details><summary>Legacy percentage marker evidence</summary><p className="subtle">Historical percentage markers remain read-only. They are not interpreted as entrance zones and do not satisfy Step 06.</p><ul>{openings.map((item) => <li key={item.id}>{item.kind.replaceAll("_", " ")} · {(item.markerX * 100).toFixed(2)}% left · {(item.markerY * 100).toFixed(2)}% top · {item.createdAt}</li>)}</ul></details> : null}
    </article>

    {evidenceHistoryDetails}
    <details className="card span-12"><summary>Details · deferred computed mapping</summary><p className="subtle">Computed 16D geometry, automatic sector labels, and space findings are deferred. They are not Step 06 operator tasks. Existing historical computed records remain read-only.</p><p className="meta">{spaces.length} historical computed mapping record{spaces.length === 1 ? "" : "s"}.</p><button className="button-secondary" type="button" disabled>Computed 16D mapping is deferred</button></details>
    <div className="footer-note spatial-focused-message" role={/could not|failed|changed|required|blocked/i.test(message) ? "alert" : "status"} aria-live="polite">{message}</div>
  </section>;

  return <section className={`section-grid spatial-workspace spatial-focus-${focus}`} aria-labelledby="spatial-title">
    <div className="card span-12"><div className="eyebrow">Project and floor context</div><h1 id="spatial-title">Set up the selected floor</h1><p className="subtle">The project shares the client and orientation. Plans, marked evidence, mappings, evaluations, and reports remain separate for every floor.</p><div className="founder-context-bar" aria-label="Locked spatial context"><span>Case</span><strong>{caseRecord?.caseNumber ?? (requestedCaseMissing ? "CASE_NOT_ACCESSIBLE" : "Select a case to continue")}</strong><span aria-hidden="true">→</span><span>{client?.displayName ?? (requestedCaseMissing ? "Case context unavailable" : "Client unavailable")}</span><span aria-hidden="true">→</span><span>{project?.propertyName ?? (requestedCaseMissing ? "Project context unavailable" : "Project unavailable")}</span><span aria-hidden="true">→</span><span>{floor?.floorLabel ?? (requestedFloorMissing ? "FLOOR_NOT_ACCESSIBLE" : requestedFloorMismatch ? "FLOOR_CASE_MISMATCH" : "Select a floor to continue")}</span></div>{requestedCaseMissing ? <p className="blocked-note" role="alert">CASE_NOT_ACCESSIBLE — the requested case does not exist or is outside your organisation.</p> : requestedFloorMissing ? <p className="blocked-note" role="alert">FLOOR_NOT_ACCESSIBLE — the requested floor does not exist or is outside your organisation.</p> : requestedFloorMismatch ? <p className="blocked-note" role="alert">FLOOR_CASE_MISMATCH — the requested floor does not belong to this case.</p> : !caseRecord || !floor ? <p className="blocked-note" role="alert">Select an authorised case and floor from the global case selector before editing spatial evidence.</p> : null}<div className="pill-row"><span className="pill">Project {project ? "open" : "not ready"}</span><span className="pill">{floors.length} floor{floors.length === 1 ? "" : "s"}</span><span className="pill">{orientation ? `${orientation.exactDegree}° locked` : "Orientation not locked"}</span></div></div>

    <div className="card span-6"><div className="eyebrow">Step 1</div><h2>Current digital plan</h2><p className="subtle">Upload the clean plan used for computation. A replacement supersedes the old version without deleting it.</p><div className={`founder-flow-status ${planUploadState === "FAILED" ? "status-blocked" : planUploadState === "RECORDED" ? "status-ready" : ""}`} role={planUploadState === "FAILED" ? "alert" : "status"} aria-live="polite"><strong>Plan status: {planUploadState.replaceAll("_", " ")}</strong>{file ? <span className="meta"> {file.name.replace(/[\r\n]/g, " ")} · {file.type || "unknown type"} · {readableFileSize(file.size)}</span> : null}{planUploadState === "UPLOADING" ? <span> Uploading securely…</span> : null}{planUploadState === "UPLOADED_NOT_RECORDED" ? <span> Uploaded securely; record the plan version next.</span> : null}{planUploadState === "RECORDED" ? <span> Protected floor plan uploaded securely and recorded.</span> : null}{planUploadError ? <p>{planUploadError}</p> : null}</div><div className="field"><label htmlFor="plan-file">Plan file</label><input id="plan-file" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp" onChange={(event) => { const selected = event.target.files?.[0] ?? null; setFile(selected); setPlanUploadError(""); setPlanUploadState(selected ? "SELECTED" : "NOT_SELECTED"); }} /><button className="button-secondary" type="button" disabled={!file || busy || !floor} onClick={() => { if (!file) return; setPlanUploadState("UPLOADING"); setPlanUploadError(""); void upload(file, floor?.floorLabel, (asset) => { setPlanAssetRef(asset.evidenceRef); setPlanUploadState("UPLOADED_NOT_RECORDED"); }, (error) => { setPlanUploadState("FAILED"); setPlanUploadError(error); }); }}>{planUploadState === "FAILED" ? "Retry protected plan upload" : "Upload protected plan"}</button><p className="meta">{file ? "Selected file is ready to upload." : "Upload is disabled until a file is selected."}</p></div><div className="field"><label htmlFor="plan-version">Version name</label><input id="plan-version" value={planVersion} onChange={(event) => setPlanVersion(event.target.value)} placeholder="Example: Architect plan 03" maxLength={80} /></div><div className="field"><label htmlFor="plan-asset">Uploaded plan</label><select id="plan-asset" value={planAssetRef} onChange={(event) => { const nextRef = event.target.value; setPlanAssetRef(nextRef); setPlanUploadState(nextRef ? nextRef === plan?.protectedFileRef ? "RECORDED" : "UPLOADED_NOT_RECORDED" : "NOT_SELECTED"); }}><option value="">Choose a file</option>{assets.map((asset) => <option key={asset.id} value={asset.evidenceRef}>{asset.fileName}</option>)}</select></div><button className="button" type="button" disabled={busy || !floor || !planVersion.trim() || !planAssetRef || selectedPlanIsCurrent} onClick={() => { if (replacingPlan && !window.confirm("Record this as a new floor plan version? The current plan remains in immutable history and dependent work will require regeneration.")) return; void (async () => { const recorded = await run("plan-version-create", { floorId: floor?.id, versionLabel: planVersion, evidenceRef: planAssetRef }, replacingPlan ? "Replacement floor plan recorded as a new immutable version." : "Current plan version recorded."); if (recorded) setPlanUploadState("RECORDED"); })(); }}>{selectedPlanIsCurrent ? "Current plan recorded" : replacingPlan ? "Record replacement plan" : "Record current plan"}</button><p className="meta">{selectedPlanIsCurrent ? "This exact protected file is already the current plan." : !planAssetRef ? "Record is disabled until a protected upload is selected." : !planVersion.trim() ? "Record is disabled until a version name is entered." : replacingPlan ? "Recording creates a new immutable plan version after confirmation." : "Ready to record this protected plan."}</p>{plan && <p className="meta">Current: {plan.versionLabel}</p>}</div>

    <div className="card span-6"><div className="eyebrow">Step 2</div><h2>Original hand-marked evidence · 32-sector chakra</h2><p className="subtle">Select the original full-colour hand-marked evidence scan and confirm that the 32-sector chakra overlay is visibly present. No sector labels or geometry are inferred by the system.</p><div className="field"><label htmlFor="marked-asset">Full-colour 32-sector marked scan</label><select id="marked-asset" value={markedAssetRef} onChange={(event) => setMarkedAssetRef(event.target.value)}><option value="">Choose a protected file</option>{assets.map((asset) => <option key={asset.id} value={asset.evidenceRef}>{asset.fileName}</option>)}</select></div><label className="check-row" htmlFor="has-32-sector-chakra"><input id="has-32-sector-chakra" type="checkbox" checked={has32SectorChakra} onChange={(event) => setHas32SectorChakra(event.target.checked)} /> Founder confirmation: the 32-sector chakra overlay is visibly present.</label><button className="button" type="button" disabled={busy || !floor || !plan || !markedAssetRef || !has32SectorChakra || selectedMarkedIsCurrent} onClick={() => void run("spatial-evidence-create", { floorId: floor?.id, planVersionId: plan?.id, kind: "HAND_MARKED_PLAN", classification: "MARKED_32D_CHAKRA_V1", has32SectorChakra: true, evidenceRef: markedAssetRef, fullColourConfirmed: true }, "32-sector chakra evidence recorded and Founder-confirmed.")}>{selectedMarkedIsCurrent ? "32D evidence recorded" : markedEvidence ? "Record replacement 32D evidence" : "Confirm 32D evidence"}</button><p className="meta">{selectedMarkedIsCurrent ? "This exact protected file is already the current immutable 32D evidence." : !markedAssetRef ? "Choose the protected 32D evidence file." : !has32SectorChakra ? "Confirm that the 32-sector chakra overlay is visibly present." : markedEvidence ? "Ready to record a replacement immutable version." : "Ready to confirm the 32D evidence."}</p></div>

    <div className="card span-6"><div className="eyebrow">Step 3</div><h2>16-direction marked mapping</h2><p className="subtle">Select a separate manually prepared 16-direction marked mapping for this exact floor and plan. Computed 16D geometry and sector labels remain deferred.</p><div className="field"><label htmlFor="marked-16-asset">Full-colour 16-direction marked mapping</label><select id="marked-16-asset" value={marked16AssetRef} onChange={(event) => setMarked16AssetRef(event.target.value)}><option value="">Choose a protected file</option>{assets.map((asset) => <option key={asset.id} value={asset.evidenceRef}>{asset.fileName}</option>)}</select></div><label className="check-row" htmlFor="has-16-direction-mapping"><input id="has-16-direction-mapping" type="checkbox" checked={has16DirectionMapping} onChange={(event) => setHas16DirectionMapping(event.target.checked)} /> Founder confirmation: this 16-direction mapping belongs to this floor and plan.</label><button className="button" type="button" disabled={busy || !floor || !plan || !marked16AssetRef || !has16DirectionMapping || selectedMarked16IsCurrent} onClick={() => void run("spatial-evidence-create", { floorId: floor?.id, planVersionId: plan?.id, kind: "HAND_MARKED_PLAN", classification: "MARKED_16D_MAPPING_V1", has16DirectionMapping: true, evidenceRef: marked16AssetRef, fullColourConfirmed: true }, "16-direction marked mapping recorded and Founder-confirmed.")}>{selectedMarked16IsCurrent ? "16D evidence recorded" : marked16Evidence ? "Record replacement 16D evidence" : "Confirm 16D evidence"}</button><p className="meta">{selectedMarked16IsCurrent ? "This exact protected file is already the current immutable 16D evidence." : !marked16AssetRef ? "Choose the protected 16D mapping file." : !has16DirectionMapping ? "Confirm that this mapping belongs to the selected floor and plan." : marked16Evidence ? "Ready to record a replacement immutable version." : "Ready to confirm the 16D evidence."}</p></div>

    <div className="card span-12"><div className="eyebrow">Step 4</div><h2>Google Earth evidence and exact orientation</h2><p className="subtle">Upload the Google Earth screenshot at project level, record it, then deliberately lock the exact degree. Direction boundaries are not guessed here.</p>
      <div className={`founder-flow-status ${googleUploadState === "FAILED" ? "status-blocked" : googleUploadState === "RECORDED" ? "status-ready" : ""}`} role={googleUploadState === "FAILED" ? "alert" : "status"} aria-live="polite"><strong>Evidence status: {googleUploadState.replaceAll("_", " ")}</strong>{caseFile && <span className="meta"> {caseFile.name.replace(/[\r\n]/g, " ")} · {caseFile.type || "unknown type"} · {readableFileSize(caseFile.size)}</span>}{googleUploadState === "UPLOADING" && <span> Uploading securely…</span>}{googleUploadState === "UPLOADED_NOT_RECORDED" && <span> Uploaded securely; record it before locking.</span>}{googleUploadState === "RECORDED" && <span> Google Earth screenshot uploaded securely and recorded.</span>}{googleUploadError && <p>{googleUploadError}</p>}</div>
      <div className="two-col"><div className="field"><label htmlFor="google-file">Google Earth screenshot</label><input ref={googleFileRef} id="google-file" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp" aria-invalid={Boolean(orientationErrors.googleEvidence)} aria-describedby={orientationErrors.googleEvidence ? "google-file-error" : undefined} onChange={(event) => { const selected = event.target.files?.[0] ?? null; setCaseFile(selected); setGoogleUploadError(""); setGoogleUploadState(selected ? "SELECTED" : "NOT_SELECTED"); setOrientationErrors((current) => ({ ...current, googleEvidence: "" })); }} />{orientationErrors.googleEvidence && <p id="google-file-error" className="field-error">{orientationErrors.googleEvidence}</p>}<button className="button-secondary" type="button" disabled={!caseFile || busy} onClick={() => { if (!caseFile) return; setGoogleUploadState("UPLOADING"); setGoogleUploadError(""); void upload(caseFile, undefined, (asset) => { setGoogleAssetRef(asset.evidenceRef); setGoogleUploadState("UPLOADED_NOT_RECORDED"); }, (error) => { setGoogleUploadState("FAILED"); setGoogleUploadError(error); }); }}>{googleUploadState === "FAILED" ? "Retry upload" : "Upload screenshot"}</button><p className="meta">{caseFile ? "Selected file is ready to upload." : "Upload is disabled until a file is selected."}</p></div>
      <div className="field"><label htmlFor="google-asset">Uploaded screenshot</label><select ref={googleAssetControlRef} id="google-asset" value={googleAssetRef} aria-invalid={Boolean(orientationErrors.googleEvidence)} aria-describedby={orientationErrors.googleEvidence ? "google-file-error" : undefined} onChange={(event) => { const nextRef = event.target.value; setGoogleAssetRef(nextRef); if (nextRef) { setGoogleUploadState(nextRef === googleEvidence?.protectedFileRef ? "RECORDED" : "UPLOADED_NOT_RECORDED"); setOrientationErrors((current) => ({ ...current, googleEvidence: "" })); } else setGoogleUploadState("NOT_SELECTED"); }}><option value="">Choose a project file</option>{caseAssets.map((asset) => <option key={asset.id} value={asset.evidenceRef}>{asset.fileName}</option>)}</select><button className="button-secondary" type="button" disabled={busy || !googleAssetRef || selectedGoogleEvidenceIsCurrent} onClick={() => { if (replacingGoogleEvidence && !window.confirm("Record this as a new Google Earth evidence version? The current version remains in immutable history.")) return; void (async () => { const recorded = await run("spatial-evidence-create", { kind: "GOOGLE_EARTH_ORIENTATION", evidenceRef: googleAssetRef, fullColourConfirmed: true }, replacingGoogleEvidence ? "Replacement Google Earth orientation evidence recorded as a new version." : "Google Earth orientation evidence recorded."); if (recorded) setGoogleUploadState("RECORDED"); })(); }}>{selectedGoogleEvidenceIsCurrent ? "Current file recorded" : replacingGoogleEvidence ? "Record replacement file" : "Record orientation evidence"}</button><p className="meta">{selectedGoogleEvidenceIsCurrent ? "This exact protected file is already the current recorded evidence." : googleAssetRef ? replacingGoogleEvidence ? "Recording creates a new immutable evidence version after confirmation." : "Record is available after upload completes." : "Record is disabled until an uploaded file is selected."}</p></div>
      <div className={`field ${orientationErrors.degree ? "field-invalid" : ""}`}><label htmlFor="orientation-degree">Exact degree (0 to less than 360)</label><input ref={degreeRef} id="orientation-degree" type="number" min="0" max="359.9999" step="0.0001" value={degree} aria-invalid={Boolean(orientationErrors.degree)} aria-describedby={orientationErrors.degree ? "orientation-degree-error" : undefined} onBlur={(event) => { const error = degreeValidation(event.currentTarget.value); setOrientationErrors((current) => ({ ...current, degree: error })); }} onChange={(event) => { setDegree(event.target.value); setOrientationErrors((current) => ({ ...current, degree: "" })); }} />{orientationErrors.degree && <p id="orientation-degree-error" className="field-error" role="alert">{orientationErrors.degree}</p>}</div>
      <div className={`field ${orientationErrors.reason ? "field-invalid" : ""}`}><label htmlFor="orientation-reason">Why this orientation is correct</label><textarea ref={reasonRef} id="orientation-reason" value={orientationReason} aria-invalid={Boolean(orientationErrors.reason)} aria-describedby={orientationErrors.reason ? "orientation-reason-error" : undefined} onBlur={(event) => { const error = reasonValidation(event.currentTarget.value); setOrientationErrors((current) => ({ ...current, reason: error })); }} onChange={(event) => { setOrientationReason(event.target.value); setOrientationErrors((current) => ({ ...current, reason: "" })); }} minLength={20} maxLength={500} />{orientationErrors.reason && <p id="orientation-reason-error" className="field-error" role="alert">{orientationErrors.reason}</p>}</div></div>
      <button className="button" type="button" disabled={busy || !googleEvidence || (isV1Spatial ? (orientation ? nativeD8Ready : Boolean(currentDegreeError) || Boolean(currentReasonError)) : !orientation || Boolean(currentDegreeError) || Boolean(currentReasonError) || orientationUnchanged)} onClick={() => {
        if (isV1Spatial) {
          if (!googleEvidence) return;
          if (!orientation) {
            const errors = validateOrientation();
            if (Object.keys(errors).length) { focusFirstOrientationError(errors); return; }
            if (window.confirm("Lock this exact orientation? Changing it later requires new evidence and regenerates dependent work.")) void run("orientation-version-lock", { exactDegree: Number(degree), googleEarthEvidenceVersionId: googleEvidence.id, reason: orientationReason }, "Exact orientation locked with immutable evidence.");
            return;
          }
          if (!nativeD8Ready) void run("d8-orientation-finalize-v1", { projectId: project?.id, floorId: floor?.id, orientationVersionId: orientation.id, orientationEvidenceVersionId: googleEvidence.id, exactDegree: orientation.exactDegree }, "Native V1 D8 orientation finalized from the locked orientation.");
          return;
        }
        const errors = validateOrientation();
        if (Object.keys(errors).length) { focusFirstOrientationError(errors); return; }
        if (window.confirm("Lock this exact orientation? Changing it later requires new evidence and regenerates dependent work.")) void run("orientation-version-lock", { exactDegree: Number(degree), googleEarthEvidenceVersionId: googleEvidence?.id, reason: orientationReason }, "Exact orientation locked with immutable evidence.");
      }}>{isV1Spatial ? (nativeD8Ready ? "Native V1 D8 finalized" : orientation ? "Finalize native V1 D8" : "Lock exact orientation") : orientationUnchanged ? "Orientation locked" : orientation ? "Create a new orientation version" : "Lock exact orientation"}</button><p className="meta">{!googleEvidence ? "Lock is disabled until evidence is recorded." : !orientation ? "Lock the exact orientation before finalizing native V1 D8." : isV1Spatial ? (nativeD8Ready ? "Native V1 D8 is finalized from this locked orientation." : "Ready to finalize the native V1 D8 authority from the locked orientation.") : currentDegreeError ? `Lock is disabled: ${currentDegreeError}` : currentReasonError ? `Lock is disabled: ${currentReasonError}` : orientationUnchanged ? "This exact evidence, degree and rationale are already locked." : "Ready to lock the exact orientation."}</p></div>

    <div className="card span-6"><div className="eyebrow">Step 4 · 32 directions</div><h2>Entrances and windows</h2><p className="subtle">Place verified markers using percentages from the left and top of the current plan. Automatic direction naming remains blocked until its methodology version is approved.</p><div className="field"><label htmlFor="opening-kind">Opening type</label><select id="opening-kind" value={openingKind} onChange={(event) => setOpeningKind(event.target.value)}><option value="MAIN_ENTRANCE">Main entrance</option><option value="ENTRANCE">Other entrance</option><option value="WINDOW">Window</option></select></div><div className="two-col"><div className={`field ${openingErrors.x ? "field-invalid" : ""}`}><label htmlFor="opening-x">From left (%)</label><input id="opening-x" type="number" min="0" max="100" value={openingX} aria-invalid={Boolean(openingErrors.x)} aria-describedby={openingErrors.x ? "opening-x-error" : undefined} onBlur={() => setOpeningErrors((current) => ({ ...current, x: openingXError }))} onChange={(event) => { setOpeningX(event.target.value); setOpeningErrors((current) => ({ ...current, x: "" })); }} />{openingErrors.x ? <p id="opening-x-error" className="field-error" role="alert">{openingErrors.x}</p> : null}</div><div className={`field ${openingErrors.y ? "field-invalid" : ""}`}><label htmlFor="opening-y">From top (%)</label><input id="opening-y" type="number" min="0" max="100" value={openingY} aria-invalid={Boolean(openingErrors.y)} aria-describedby={openingErrors.y ? "opening-y-error" : undefined} onBlur={() => setOpeningErrors((current) => ({ ...current, y: openingYError }))} onChange={(event) => { setOpeningY(event.target.value); setOpeningErrors((current) => ({ ...current, y: "" })); }} />{openingErrors.y ? <p id="opening-y-error" className="field-error" role="alert">{openingErrors.y}</p> : null}</div></div><button className="button" type="button" disabled={busy || !readyForMapping || Boolean(openingXError) || Boolean(openingYError) || openingDuplicate} onClick={() => void run("opening-mapping-create", { floorId: floor?.id, planVersionId: plan?.id, orientationVersionId: orientation?.id, evidenceVersionId: markedEvidence?.id, kind: openingKind, markerX: Number(openingX) / 100, markerY: Number(openingY) / 100, verified: true }, "Verified opening marker saved. Direction classification awaits approved methodology.")}>{openingDuplicate ? "Marker already recorded" : "Save verified marker"}</button><p className="meta">{!readyForMapping ? "Marker saving is disabled until the current plan, locked orientation and 32D evidence are ready." : openingXError ? `Marker saving is disabled: ${openingXError}` : openingYError ? `Marker saving is disabled: ${openingYError}` : openingDuplicate ? "This exact opening type and position are already recorded." : `Ready to save. ${openings.length} marker${openings.length === 1 ? "" : "s"} currently belong to this floor version.`}</p></div>

    <div className="card span-6"><div className="eyebrow">Step 5 · 16 directions</div><h2>Mapped spaces (V4 deferred)</h2><p className="subtle">Computed 16-direction geometry, sector labels, and space findings are deferred to V4. The separate manually prepared 16-direction marked mapping above remains the authoritative evidence record.</p><p className="meta">{spaces.length} historical computed mapping record{spaces.length === 1 ? "" : "s"} remain read-only.</p><button className="button-secondary" type="button" disabled>Computed 16D mapping is deferred</button></div>

    <div className="card span-12"><div className="eyebrow">Next step</div><h2>{readyForMapping && openings.some((item) => item.kind === "MAIN_ENTRANCE") ? "Spatial evidence is recorded" : "Finish the missing spatial step"}</h2><p className="subtle">Evaluation readiness reflects the current plan, full-colour marked evidence, locked orientation, and the applicable entrance classifications. Main Entrance is the property-level primary classification; Floor Entrance is a floor-specific secondary classification when applicable.</p><a className="button-secondary" href={`/founder/continue${requestedCaseId || requestedFloorId ? `?${new URLSearchParams({ ...(requestedCaseId ? { caseId: requestedCaseId } : {}), ...(requestedFloorId ? { floorId: requestedFloorId } : {}) }).toString()}` : ""}`}>Continue to evaluation readiness</a><div className="footer-note" role={/could not|failed|changed|required|blocked/i.test(message) ? "alert" : "status"} aria-live="polite">{message}</div></div>

    <div className="card span-12"><div className="eyebrow">Founder floor queues</div><h2>Resolve one floor without changing another</h2><p className="subtle">Each blocker names the exact next action. A blocker clears only after a new valid version is bound and verified.</p><div className="field"><label htmlFor="regeneration-reason">Reason for this regeneration step</label><textarea id="regeneration-reason" value={regenerationReason} onChange={(event) => setRegenerationReason(event.target.value)} minLength={20} maxLength={500} placeholder="Explain the evidence or version change and what was checked." /></div>{founderQueues.map((queue) => <article className="next-step-card" key={queue.floorId}><div className="pill-row"><span className="pill">{queue.floorLabel}</span><span className="pill">{queue.category.replaceAll("_", " ")}</span></div><h3>{queue.nextAction}</h3><p className="subtle">{queue.blockerReason}</p>{queue.invalidations.map((item) => { const options = replacementOptions(item.targetType); const nextStatus = item.status === "NEEDS_REGENERATION" ? "REPLACEMENT_REQUIRED" : item.status === "REPLACEMENT_REQUIRED" ? "REGENERATED" : "READY_FOR_REVIEW"; return <div className="field" key={item.id}><strong>{item.targetType.replaceAll("_", " ")}</strong><span className="meta">Current state: {item.status.replaceAll("_", " ")}</span>{item.status === "REPLACEMENT_REQUIRED" ? <><label htmlFor={`replacement-${item.id}`}>New valid version</label><select id={`replacement-${item.id}`} value={replacementVersionId[item.id] ?? ""} onChange={(event) => setReplacementVersionId((current) => ({ ...current, [item.id]: event.target.value }))}><option value="">Choose the exact replacement</option>{options.filter((option) => option.id !== item.targetId).map((option) => <option key={option.id} value={option.id}>{option.label}</option>)}</select></> : null}<button className="button-secondary" type="button" disabled={busy || regenerationReason.trim().length < 20 || (item.status === "REPLACEMENT_REQUIRED" && !replacementVersionId[item.id])} onClick={() => void run("regeneration-transition", { floorId: queue.floorId, invalidationId: item.id, toStatus: nextStatus, replacementVersionId: replacementVersionId[item.id], reason: regenerationReason }, `${item.targetType.replaceAll("_", " ")} moved to ${nextStatus.replaceAll("_", " ")}.`, item.recordVersion)}>{nextStatus === "REPLACEMENT_REQUIRED" ? "Require replacement" : nextStatus === "REGENERATED" ? "Bind regenerated version" : "Verify and mark ready"}</button></div>; })}</article>)}</div>
    {focus !== "all" ? <div className="footer-note spatial-focused-message" role={/could not|failed|changed|required|blocked/i.test(message) ? "alert" : "status"} aria-live="polite">{message}</div> : null}
  </section>;
}
